-- Publish only after deploying the YouTube-capable frontend.
begin;
-- Remove the previous generated loops, including their demo copies.
delete from public.songs where author='Voib Studio' and song_path in ('/demo/neon-drift.mp3','/demo/afterglow.mp3','/demo/quiet-orbit.mp3');
on conflict(youtube_id) do update set title=excluded.title,author=excluded.author,image_path=excluded.image_path,artists=excluded.artists,genres=excluded.genres,collections=excluded.collections,source_channel=excluded.source_channel,source_channel_url=excluded.source_channel_url;
commit;
